/* ---------- 一键样式表与多插件引用计数挂载器 ---------- */

const sidebarRulesOnlyCss = sidebarTokensCss.startsWith(glassTokensCss)
  ? sidebarTokensCss.slice(glassTokensCss.length).trim()
  : sidebarTokensCss

/**
 * 通用插件基础组件一键样式表（不含侧栏 [data-hs] 灰阶，普通主界面插件一行即可注入全部原语样式）。
 */
export const dshUiCss = [
  glassTokensCss,
  iconBaseCss,
  buttonCss,
  controlsCss,
  menuSurfaceCss,
  popoverCss,
  modalCss,
  fallbackCss,
  toastCss,
  tooltipCss,
  infoTipCss,
  feedbackCss,
].join('\n')

/**
 * 完整独立样式表（含全部基础原语样式 + [data-hs] 侧栏与壁纸感知五阶交互底色，用于 dist/dsh-ui.css 与全量预览）。
 */
export const dshUiFullCss = [
  dshUiCss,
  sidebarRulesOnlyCss,
].join('\n')

/**
 * 标准分块清单：供 mountDshUiStyles 按 <style data-dsh-ui="..." data-ver="0.2.0" data-refs="n"> 挂载仲裁。
 */
export const DSH_UI_STYLE_BLOCKS: ReadonlyArray<readonly [string, string]> = [
  ['tokens', glassTokensCss],
  ['icons', iconBaseCss],
  ['button', buttonCss],
  ['icon-button', iconButtonCss],
  ['inputs', inputsCss],
  ['choices', choicesCss],
  ['navigation', navigationCss],
  ['containers', containersCss],
  ['scroll-area', scrollAreaCss],
  ['menu-surface', menuSurfaceCss],
  ['popover', popoverCss],
  ['modal', modalCss],
  ['fallback', fallbackCss],
  ['toast', toastCss],
  ['tooltip', tooltipCss],
  ['info-tip', infoTipCss],
  ['feedback', feedbackCss],
]

export interface MountDshUiStylesOptions {
  /** 是否同步挂载 [data-hs] 侧栏与壁纸五阶交互变量块（默认 false）。 */
  sidebar?: boolean
  /** 显式覆盖版本号（默认 UI_STYLE_VERSION = '0.2.0'）。 */
  version?: string
}

/**
 * 按块名、版本号与引用计数一键挂载 @kewen/dsh-ui 共享样式，返回幂等卸载清理函数。
 * 多个插件同时运行时自动复用高版本样式块并累加引用计数，单插件卸载绝不误删其他插件正在使用的基础样式。
 */
export function mountDshUiStyles(
  optionsOrBlocks?: MountDshUiStylesOptions | ReadonlyArray<readonly [string, string]>,
): () => void {
  if (Array.isArray(optionsOrBlocks)) {
    return mountUiStyles(optionsOrBlocks as ReadonlyArray<readonly [string, string]>, UI_STYLE_VERSION)
  }
  const opts = (optionsOrBlocks ?? {}) as MountDshUiStylesOptions
  const blocks: Array<readonly [string, string]> = [...DSH_UI_STYLE_BLOCKS]
  if (opts.sidebar) {
    blocks.push(['sidebar-tokens', sidebarRulesOnlyCss])
  }
  return mountUiStyles(blocks, opts.version ?? UI_STYLE_VERSION)
}
