import React, { forwardRef, type ButtonHTMLAttributes, type ReactNode } from 'react'
import { SpinnerIcon } from './icons'

export type ButtonVariant =
  | 'primary'
  | 'outline'
  | 'toolbar'
  | 'ghost'
  | 'danger-solid'
  | 'danger-ghost'
  | 'danger'

export type ButtonSize = 'md' | 'sm'

/**
 * 03 统一胶囊按钮原语（36px md / 28px sm，全圆弧胶囊 999px + 永久锁定 corner-shape: round）：
 * - 4 档常规语气（primary / outline / toolbar / ghost）+ 2 档危险语气（danger-solid / danger-ghost，旧版 danger 自动映射至 danger-ghost 保持向后兼容）；
 * - primary / danger-solid 采用 1px solid transparent + background-clip: padding-box 光学内收，抵消高反差辐照膨胀，与并排输入框严格等高；
 * - toolbar 采用同源单阶软底 --dsh-toolbar-fill*；
 * - loading 防重入态自动置为 disabled 并渲染统一 SVG 旋转指示器；
 * - 60ms 迅捷下压 scale(0.98) / 150ms 无过冲回弹 + 独立控件 2px 锐利焦点环（outline-offset: 2px）。
 */
export type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  variant?: ButtonVariant
  size?: ButtonSize
  icon?: ReactNode
  trailingIcon?: ReactNode
  loading?: boolean
  tip?: string
}

export const Button = forwardRef<HTMLButtonElement, ButtonProps>(function Button(
  {
    variant = 'ghost',
    size = 'md',
    icon,
    trailingIcon,
    loading = false,
    tip,
    disabled,
    className,
    children,
    ...rest
  },
  ref,
) {
  const resolvedVariant = variant === 'danger' ? 'danger-ghost' : variant
  const legacyDangerAlias = variant === 'danger' ? ' hs-btn-danger' : ''
  const isDisabled = Boolean(disabled || loading)

  return (
    <button
      ref={ref}
      type="button"
      disabled={isDisabled}
      aria-busy={loading || undefined}
      data-hs-tip={tip}
      className={`hs-btn hs-btn-${resolvedVariant}${legacyDangerAlias} hs-btn-${size}${loading ? ' is-loading' : ''}${className ? ` ${className}` : ''}`}
      {...rest}
    >
      {loading ? (
        <span className="hs-btn-icon" aria-hidden="true">
          <SpinnerIcon inline={false} />
        </span>
      ) : (
        icon != null && <span className="hs-btn-icon">{icon}</span>
      )}
      {children}
      {trailingIcon != null && <span className="hs-btn-chev">{trailingIcon}</span>}
    </button>
  )
})

