import React, {
  useEffect,
  useId,
  useRef,
  type CSSProperties,
  type HTMLAttributes,
  type ReactNode,
} from 'react'
import { createPortal } from 'react-dom'
import { isImeComposing } from './host-bridge'
import { CloseIcon, SpinnerIcon, WarnIcon } from './icons'

export type ModalConfirmTone = 'primary' | 'danger'

export interface ModalProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  open: boolean
  onClose: () => void
  title: ReactNode
  description?: ReactNode
  /** 危险操作警示区内容（渲染 12px 浅红底 .modal-warn-box + WarnIcon）。 */
  warning?: ReactNode
  closeLabel?: string
  hideCloseButton?: boolean
  /** 点击遮罩空白处是否关闭，默认 true。 */
  closeOnBackdrop?: boolean
  /** 按下非输入法选词态 Escape 是否关闭，默认 true。 */
  closeOnEscape?: boolean
  /** 自定义底栏节点；未传时可由 cancelLabel / confirmLabel / auxiliaryAction 自动组装标准 28px 操作栏。 */
  footer?: ReactNode
  /** 左下角辅助低频动作（通过 margin-right: auto 与右侧主次动作分离）。 */
  auxiliaryAction?: ReactNode
  cancelLabel?: ReactNode
  onCancel?: () => void
  confirmLabel?: ReactNode
  onConfirm?: () => void
  confirmTone?: ModalConfirmTone
  confirmDisabled?: boolean
  confirmLoading?: boolean
  /** 默认通过 createPortal 挂载至 document.body；传 false 支持无 DOM 静态测试。 */
  portal?: boolean
  overlayClassName?: string
  style?: CSSProperties
  children?: ReactNode
}

type InertElement = Element & { inert?: boolean }

/**
 * 统一阻断式模态弹窗（README 06.3）：
 * - 16px (--dsw-radius-lg) + --dsh-corner-shape 双轨曲率 + --dsh-surface-floating 抬升实底 + --dsw-elevation-prominent；
 * - 零模糊纯压暗遮罩 var(--dsw-alias-bg-mask-1)；
 * - 打开期间为 document.body 其余兄弟节点挂 inert 属性锁死背景 Tab 与读屏焦点，关闭时完整复原 inert 并归还焦点至触发元素；
 * - Escape 关闭自动接入 isImeComposing 守卫，防止中文输入法取消候选词时误关弹窗；
 * - 右上角 28px 正圆关闭钮（CloseIcon SVG，零字符图标），底栏统一 28px (sm) 按钮布局（左侧辅助动作 + toolbar 取消 + 最右 primary / danger-solid 主操作）。
 */
export function Modal({
  open,
  onClose,
  title,
  description,
  warning,
  closeLabel = '关闭',
  hideCloseButton = false,
  closeOnBackdrop = true,
  closeOnEscape = true,
  footer,
  auxiliaryAction,
  cancelLabel,
  onCancel,
  confirmLabel,
  onConfirm,
  confirmTone = 'primary',
  confirmDisabled = false,
  confirmLoading = false,
  portal = true,
  overlayClassName,
  className,
  style,
  children,
  ...rest
}: ModalProps) {
  const titleId = useId()
  const descId = useId()
  const overlayRef = useRef<HTMLDivElement>(null)
  const dialogRef = useRef<HTMLDivElement>(null)
  const onCloseRef = useRef(onClose)
  onCloseRef.current = onClose

  useEffect(() => {
    if (!open || typeof document === 'undefined') return

    const previousFocus =
      document.activeElement instanceof HTMLElement ? document.activeElement : null

    const overlayEl = overlayRef.current
    const restored: Array<{ el: InertElement; hadAttr: boolean; prevProp: boolean }> = []

    if (document.body && overlayEl && overlayEl.parentElement === document.body) {
      for (const sibling of Array.from(document.body.children)) {
        if (
          sibling === overlayEl
          || sibling.tagName === 'SCRIPT'
          || sibling.tagName === 'STYLE'
          || sibling.hasAttribute('data-dsh-toast')
        ) {
          continue
        }
        const inertEl = sibling as InertElement
        restored.push({
          el: inertEl,
          hadAttr: inertEl.hasAttribute('inert'),
          prevProp: Boolean(inertEl.inert),
        })
        inertEl.inert = true
        inertEl.setAttribute('inert', '')
      }
    }

    const dialogEl = dialogRef.current
    if (dialogEl && (!document.activeElement || !dialogEl.contains(document.activeElement))) {
      const autoTarget = dialogEl.querySelector<HTMLElement>(
        '[autofocus], input:not(:disabled), textarea:not(:disabled), select:not(:disabled), button:not(:disabled):not(.dsh-modal-close)',
      )
      ;(autoTarget ?? dialogEl).focus?.()
    }

    const onKeyDown = (event: KeyboardEvent) => {
      if (!closeOnEscape) return
      if (event.key !== 'Escape') return
      if (isImeComposing(event)) return
      event.stopPropagation()
      onCloseRef.current()
    }

    document.addEventListener('keydown', onKeyDown)

    return () => {
      document.removeEventListener('keydown', onKeyDown)
      for (const { el, hadAttr, prevProp } of restored) {
        el.inert = prevProp
        if (hadAttr) el.setAttribute('inert', '')
        else el.removeAttribute('inert')
      }
      if (previousFocus && previousFocus.isConnected !== false) {
        previousFocus.focus?.()
      }
    }
  }, [open, closeOnEscape])

  if (!open) return null

  const hasStructuredFooter =
    auxiliaryAction !== undefined || cancelLabel !== undefined || confirmLabel !== undefined
  const confirmVariantClass = confirmTone === 'danger' ? 'hs-btn-danger-solid' : 'hs-btn-primary'

  const renderedFooter =
    footer !== undefined ? (
      <div className="dsh-modal-foot modal-foot">{footer}</div>
    ) : hasStructuredFooter ? (
      <div className="dsh-modal-foot modal-foot">
        {auxiliaryAction !== undefined && (
          <span className="dsh-modal-aux">{auxiliaryAction}</span>
        )}
        {cancelLabel !== undefined && (
          <button
            type="button"
            className="hs-btn hs-btn-toolbar hs-btn-sm"
            onClick={() => (onCancel ?? onClose)()}
          >
            {cancelLabel}
          </button>
        )}
        {confirmLabel !== undefined && (
          <button
            type="button"
            className={`hs-btn ${confirmVariantClass} hs-btn-sm${confirmLoading ? ' is-loading' : ''}`}
            disabled={confirmDisabled || confirmLoading}
            onClick={onConfirm}
          >
            {confirmLoading && (
              <span className="hs-btn-icon" aria-hidden="true">
                <SpinnerIcon />
              </span>
            )}
            {confirmLabel}
          </button>
        )}
      </div>
    ) : null

  const a11yLabel = rest['aria-label'] ?? (typeof title === 'string' ? title : undefined)

  const overlayNode = (
    <div
      ref={overlayRef}
      data-dsh-modal-overlay=""
      className={`dsh-modal-overlay${overlayClassName ? ` ${overlayClassName}` : ''}`}
      onPointerDown={(event) => {
        if (closeOnBackdrop && event.target === event.currentTarget) {
          onClose()
        }
      }}
    >
      <div
        {...rest}
        ref={dialogRef}
        role="dialog"
        aria-modal="true"
        aria-label={a11yLabel}
        aria-labelledby={a11yLabel === undefined ? titleId : rest['aria-labelledby']}
        aria-describedby={description !== undefined ? descId : rest['aria-describedby']}
        tabIndex={-1}
        className={`dsh-modal${className ? ` ${className}` : ''}`}
        style={style}
      >
        <div className="dsh-modal-head modal-head">
          <h2 id={titleId} className="dsh-modal-title modal-title">
            {title}
          </h2>
          {!hideCloseButton && (
            <button
              type="button"
              className="dsh-modal-close icon-btn-round"
              aria-label={closeLabel}
              onClick={onClose}
            >
              <CloseIcon />
            </button>
          )}
        </div>
        {description !== undefined && (
          <p id={descId} className="dsh-modal-desc modal-desc">
            {description}
          </p>
        )}
        {warning !== undefined && (
          <div className="modal-warn-box" role="note">
            <span className="modal-warn-ico" aria-hidden="true">
              <WarnIcon />
            </span>
            <span>{warning}</span>
          </div>
        )}
        {children}
        {renderedFooter}
      </div>
    </div>
  )

  if (portal && typeof document !== 'undefined' && Boolean(document.body)) {
    return createPortal(overlayNode, document.body)
  }
  return overlayNode
}

export const modalCss = `
@keyframes dsh-dialog-in {
  from { opacity: 0; transform: scale(.97) translateY(4px); }
  to { opacity: 1; transform: none; }
}

/* 零模糊纯压暗遮罩：绝不对全屏聊天区施加高开销 backdrop-filter */
.dsh-modal-overlay,
.live-overlay {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--dsw-alias-bg-mask-1);
  overscroll-behavior: contain;
}
.live-overlay {
  z-index: 150;
  display: none;
}
.live-overlay.is-open {
  display: flex;
}

/* 16px 抬升实底模态框（--dsh-surface-floating + --dsw-elevation-prominent） */
.dsh-modal,
.live-dialog,
.modal-static {
  box-sizing: border-box;
  border-radius: var(--dsw-radius-lg, 16px);
  corner-shape: var(--dsh-corner-shape, var(--dsw-corner-shape, round));
  background: var(--dsh-surface-floating);
  color: var(--dsw-alias-label-primary);
  box-shadow: var(--dsw-elevation-prominent);
  outline: none;
}
.dsh-modal,
.live-dialog {
  width: min(420px, calc(100vw - 32px));
  padding: 20px;
  animation: dsh-dialog-in var(--dsh-dur-pop, 150ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.live-dialog {
  width: min(400px, calc(100vw - 32px));
}
.modal-static {
  width: 100%;
  padding: 18px;
}
.modal-pane[hidden] {
  display: none;
}

/* 浅色模式下弹窗自身已是纯白底，内部全部输入类控件统一切为微凹底保持层次；深色模式保持深底凹陷 */
.dsh-modal :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea),
.modal-static :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea),
.live-dialog :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea) {
  background: var(--dsh-surface-sunken);
}
body[data-ds-dark-theme] .dsh-modal :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea),
body[data-ds-dark-theme] .modal-static :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea),
body[data-ds-dark-theme] .live-dialog :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea),
html[data-theme="dark"] body .dsh-modal :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea),
html[data-theme="dark"] body .modal-static :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea),
html[data-theme="dark"] body .live-dialog :is(.dsh-input, .dsh-search, .dsh-pwd-box, .dsh-select, .dsh-textarea) {
  background: var(--dsw-alias-bg-base);
}

.dsh-modal-head,
.modal-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.dsh-modal-title,
.modal-title {
  margin: 0;
  font-size: var(--dsh-text-xl, 16px);
  font-weight: 600;
  line-height: 1.4;
  color: var(--dsw-alias-label-primary);
  text-wrap: balance;
}
.dsh-modal-close {
  all: unset;
  box-sizing: border-box;
  flex: none;
  width: var(--dsh-control-sm, 28px);
  height: var(--dsh-control-sm, 28px);
  border-radius: 50%;
  corner-shape: round;
  display: inline-grid;
  place-items: center;
  font-size: var(--dsh-text-lg, 14px);
  color: var(--dsw-alias-label-secondary);
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transition:
    background var(--dsh-dur-hover, 120ms) ease,
    color var(--dsh-dur-hover, 120ms) ease,
    transform var(--dsh-dur-release, 150ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-modal-close:active {
  background: var(--dsw-alias-interactive-bg-active);
  transform: scale(.96);
  transition-duration: var(--dsh-dur-press, 60ms);
  transition-timing-function: var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-modal-close:focus-visible {
  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsh-focus-ring-color);
  outline-offset: 2px;
}
@media (hover: hover) {
  .dsh-modal-close:hover {
    background: var(--dsw-alias-interactive-bg-hover);
    color: var(--dsw-alias-label-primary);
  }
}

.dsh-modal-desc,
.modal-desc {
  margin: 6px 0 14px;
  font-size: var(--dsh-text-md, 13px);
  line-height: 1.55;
  color: var(--dsw-alias-label-secondary);
  text-wrap: pretty;
}
.modal-warn-box {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 8px 0 12px;
  padding: 10px 12px;
  border-radius: var(--dsw-radius-md, 12px);
  corner-shape: var(--dsh-corner-shape, var(--dsw-corner-shape, round));
  background: var(--dsw-alias-interactive-bg-hover-danger);
  color: var(--dsw-alias-label-primary);
  font-size: var(--dsh-text-sm, 12px);
  line-height: 1.5;
}
.modal-warn-ico {
  flex: none;
  margin-top: 1px;
  color: var(--dsw-alias-state-error-primary);
  display: inline-grid;
  place-items: center;
  font-size: var(--dsh-text-xl, 16px);
}
.dsh-modal-foot,
.modal-foot {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  margin-top: 16px;
}
.dsh-modal-aux {
  margin-right: auto;
  display: inline-flex;
  align-items: center;
}

/* HoverCard（富内容悬浮预览卡 · 官方 16px 浮层表面，供预览台与退化卡片复用） */
.dsh-hovercard-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
@media (max-width: 640px) {
  .dsh-hovercard-grid {
    grid-template-columns: 1fr;
  }
}
.dsh-hovercard {
  box-sizing: border-box;
  padding: 10px 13px;
  border-radius: var(--dsw-radius-lg, 16px);
  corner-shape: var(--dsh-corner-shape, var(--dsw-corner-shape, round));
  display: flex;
  flex-direction: column;
  gap: 4px;
  background: var(--dsh-surface-floating);
  color: var(--dsw-alias-label-primary);
  box-shadow: var(--dsw-elevation-panel);
}
.dsh-hovercard.is-clickable {
  cursor: pointer;
  transition: background var(--dsh-dur-hover, 120ms) ease;
}
.dsh-hovercard[tabindex]:focus-visible {
  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsh-focus-ring-color);
  outline-offset: 2px;
}
@media (hover: hover) {
  .dsh-hovercard.is-clickable:hover {
    background: color-mix(in srgb, var(--dsh-surface-floating), var(--dsw-alias-label-primary) 4%);
  }
}
.dsh-hc-title {
  font-size: var(--dsh-text-md, 13px);
  font-weight: 500;
  line-height: 1.4;
}
.dsh-hc-sub {
  font-family: var(--ds-font-family-code, monospace);
  font-size: var(--dsh-text-xs, 11px);
  line-height: 1.45;
  color: var(--dsw-alias-label-tertiary);
  overflow-wrap: anywhere;
  word-break: normal;
}
@media (prefers-reduced-motion: reduce) {
  .dsh-modal,
  .live-dialog {
    animation: none;
  }
}
`
