export interface StandaloneSwitchProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange'> {
  checked: boolean
  onChange: (checked: boolean) => void
  label?: string
}

/**
 * 04-B 独立布尔开关（36x20 全圆弧胶囊 + 16px 正圆滑块）：
 * 关态滑块采用官方 --dsw-alias-switch-thumb 防止深色模式发黑，开态轨道切为 --dsh-brand-fill 并翻转反色滑块。
 */
export const StandaloneSwitch = forwardRef<HTMLButtonElement, StandaloneSwitchProps>(
  function StandaloneSwitch(
    { checked, onChange, label, disabled = false, className, onClick, ...rest },
    ref,
  ) {
    const handleClick = (event: MouseEvent<HTMLButtonElement>) => {
      onClick?.(event)
      if (event.defaultPrevented || disabled) return
      onChange(!checked)
    }

    return (
      <button
        ref={ref}
        type="button"
        role="switch"
        aria-checked={checked}
        aria-label={label ?? rest['aria-label']}
        disabled={disabled}
        className={`hs-fb-switch${className ? ` ${className}` : ''}`}
        onClick={handleClick}
        {...rest}
      >
        <span className="hs-fb-thumb" aria-hidden="true" />
      </button>
    )
  },
)

export const Switch = StandaloneSwitch

export type CheckboxChecked = boolean | 'mixed'

export interface CheckboxProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange' | 'checked'> {
  checked: CheckboxChecked
  onChange?: (checked: boolean) => void
  label?: ReactNode
  wrapperClassName?: string
}

export const Checkbox = forwardRef<HTMLButtonElement, CheckboxProps>(function Checkbox(
  {
    checked,
    onChange,
    label,
    disabled = false,
    className,
    wrapperClassName,
    onClick,
    ...rest
  },
  ref,
) {
  const nextValue = checked !== true
  const trigger = () => {
    if (disabled) return
    onChange?.(nextValue)
  }

  const buttonNode = (
    <button
      ref={ref}
      type="button"
      role="checkbox"
      aria-checked={checked === 'mixed' ? 'mixed' : checked}
      disabled={disabled}
      className={`dsh-checkbox${className ? ` ${className}` : ''}`}
      onClick={(event) => {
        onClick?.(event)
        if (event.defaultPrevented) return
        event.stopPropagation()
        trigger()
      }}
      {...rest}
    >
      <CheckIcon size={11} inline={false} className="dsh-chk-tick" />
      <svg
        viewBox="0 0 16 16"
        width={11}
        height={11}
        fill="none"
        stroke="currentColor"
        strokeWidth={2}
        strokeLinecap="round"
        focusable="false"
        aria-hidden="true"
        className="dsh-icon dsh-chk-dash"
      >
        <path d="M3.5 8h9" />
      </svg>
    </button>
  )

  if (label === undefined) return buttonNode

  return (
    <label
      className={`dsh-check-label${disabled ? ' is-disabled' : ''}${wrapperClassName ? ` ${wrapperClassName}` : ''}`}
      onClick={(event) => {
        event.preventDefault()
        trigger()
      }}
    >
      {buttonNode}
      <span>{label}</span>
    </label>
  )
})

export interface RadioProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange' | 'checked'> {
  checked: boolean
  onSelect?: () => void
  label?: ReactNode
  wrapperClassName?: string
}

export const Radio = forwardRef<HTMLButtonElement, RadioProps>(function Radio(
  {
    checked,
    onSelect,
    label,
    disabled = false,
    className,
    wrapperClassName,
    tabIndex,
    onClick,
    ...rest
  },
  ref,
) {
  const trigger = () => {
    if (disabled) return
    onSelect?.()
  }

  const buttonNode = (
    <button
      ref={ref}
      type="button"
      role="radio"
      aria-checked={checked}
      disabled={disabled}
      tabIndex={tabIndex}
      className={`dsh-radio${className ? ` ${className}` : ''}`}
      onClick={(event) => {
        onClick?.(event)
        if (event.defaultPrevented) return
        event.stopPropagation()
        trigger()
      }}
      {...rest}
    />
  )

  if (label === undefined) return buttonNode

  return (
    <label
      className={`dsh-check-label${disabled ? ' is-disabled' : ''}${wrapperClassName ? ` ${wrapperClassName}` : ''}`}
      onClick={(event) => {
        event.preventDefault()
        trigger()
      }}
    >
      {buttonNode}
      <span>{label}</span>
    </label>
  )
})

export interface RadioOption<T extends string = string> {
  value: T
  label: ReactNode
  disabled?: boolean
}

export interface RadioGroupProps<T extends string = string>
  extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  options?: readonly RadioOption<T>[]
  value: T
  onChange: (value: T) => void
  ariaLabel?: string
}

export function RadioGroup<T extends string = string>({
  options,
  value,
  onChange,
  ariaLabel,
  className,
  onKeyDown,
  children,
  ...rest
}: RadioGroupProps<T>) {
  const firstEnabledIdx = options?.findIndex((opt) => !opt.disabled) ?? 0
  const hasSelected = options?.some((opt) => !opt.disabled && opt.value === value) ?? false

  return (
    <div
      role="radiogroup"
      aria-label={ariaLabel ?? rest['aria-label']}
      className={`dsh-radio-group${className ? ` ${className}` : ''}`}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (!event.defaultPrevented) handleRovingKeyDown(event, '.dsh-radio, [role="radio"]')
      }}
      {...rest}
    >
      {options
        ? options.map((opt, idx) => {
            const active = opt.value === value
            const stop = !opt.disabled && (active || (!hasSelected && idx === firstEnabledIdx))
            return (
              <Radio
                key={opt.value}
                checked={active}
                disabled={opt.disabled}
                tabIndex={stop ? 0 : -1}
                label={opt.label}
                onSelect={() => onChange(opt.value)}
              />
            )
          })
        : children}
    </div>
  )
}

export interface RadioCardProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'title' | 'onSelect'> {
  checked: boolean
  title: ReactNode
  description?: ReactNode
  preview?: ReactNode
  onSelect?: () => void
}

/**
 * 04-B 图文单选卡片（外卡 16px - 边距 8px = 内示意窗 8px 严格同心 + 右上角 16x16 勾选圆标）：
 */
export const RadioCard = forwardRef<HTMLButtonElement, RadioCardProps>(function RadioCard(
  {
    checked,
    title,
    description,
    preview,
    onSelect,
    disabled = false,
    className,
    onClick,
    children,
    ...rest
  },
  ref,
) {
  return (
    <button
      ref={ref}
      type="button"
      role="radio"
      aria-checked={checked}
      disabled={disabled}
      className={`dsh-rcard${className ? ` ${className}` : ''}`}
      onClick={(event) => {
        onClick?.(event)
        if (event.defaultPrevented || disabled) return
        onSelect?.()
      }}
      {...rest}
    >
      {preview !== undefined && <div className="dsh-rcard-fig">{preview}</div>}
      <div className="dsh-rcard-head">
        <span>{title}</span>
        <span className="dsh-rcard-mark" aria-hidden="true">
          <CheckIcon size={10} inline={false} />
        </span>
      </div>
      {description !== undefined && <div className="dsh-rcard-sub">{description}</div>}
      {children}
    </button>
  )
})

export interface RadioCardOption<T extends string = string> {
  value: T
  title: ReactNode
  description?: ReactNode
  preview?: ReactNode
  disabled?: boolean
}

export interface RadioCardGroupProps<T extends string = string>
  extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  options?: readonly RadioCardOption<T>[]
  value: T
  onChange: (value: T) => void
  ariaLabel?: string
}

export function RadioCardGroup<T extends string = string>({
  options,
  value,
  onChange,
  ariaLabel,
  className,
  onKeyDown,
  children,
  ...rest
}: RadioCardGroupProps<T>) {
  const firstEnabledIdx = options?.findIndex((opt) => !opt.disabled) ?? 0
  const hasSelected = options?.some((opt) => !opt.disabled && opt.value === value) ?? false

  return (
    <div
      role="radiogroup"
      aria-label={ariaLabel ?? rest['aria-label']}
      className={`dsh-rcard-grid${className ? ` ${className}` : ''}`}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (!event.defaultPrevented) handleRovingKeyDown(event, '.dsh-rcard, [role="radio"]')
      }}
      {...rest}
    >
      {options
        ? options.map((opt, idx) => {
            const active = opt.value === value
            const stop = !opt.disabled && (active || (!hasSelected && idx === firstEnabledIdx))
            return (
              <RadioCard
                key={opt.value}
                checked={active}
                disabled={opt.disabled}
                tabIndex={stop ? 0 : -1}
                title={opt.title}
                description={opt.description}
                preview={opt.preview}
                onSelect={() => onChange(opt.value)}
              />
            )
          })
        : children}
    </div>
  )
}

export interface SliderProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'value' | 'onChange'> {
  value: number
  min?: number
  max?: number
  step?: number
  onChange: (value: number) => void
  label?: ReactNode
  formatValue?: (value: number) => ReactNode
  showValue?: boolean
  wrapperClassName?: string
}

export const Slider = forwardRef<HTMLInputElement, SliderProps>(function Slider(
  {
    value,
    min = 0,
    max = 100,
    step = 1,
    onChange,
    label,
    formatValue,
    showValue = label !== undefined || formatValue !== undefined,
    wrapperClassName,
    className,
    style,
    ...rest
  },
  ref,
) {
  const span = max - min
  const clamped = Math.min(max, Math.max(min, value))
  const pct = span > 0 ? ((clamped - min) / span) * 100 : 0
  const rangeStyle = {
    ...style,
    '--pct': `${pct.toFixed(1)}%`,
  } as CSSProperties

  const inputEl = (
    <input
      ref={ref}
      type="range"
      min={min}
      max={max}
      step={step}
      value={value}
      aria-label={typeof label === 'string' && !rest['aria-label'] ? label : rest['aria-label']}
      style={rangeStyle}
      className={`dsh-range${className ? ` ${className}` : ''}`}
      onChange={(event) => onChange(Number(event.target.value))}
      {...rest}
    />
  )

  if (label === undefined && !showValue) return inputEl

  const displayVal = formatValue ? formatValue(value) : String(value)

  return (
    <div className={`dsh-slider-row${wrapperClassName ? ` ${wrapperClassName}` : ''}`}>
      <div className="dsh-slider-head">
        {label !== undefined ? <span>{label}</span> : <span />}
        {showValue && <span className="dsh-slider-val">{displayVal}</span>}
      </div>
      {inputEl}
    </div>
  )
})

