import React, { useRef, type HTMLAttributes, type ReactNode } from 'react'
import { handleRovingKeyDown, useSlidingIndicator } from './motion'

export interface SegmentedOption<T extends string = string> {
  value: T
  label: ReactNode
  disabled?: boolean
}

export interface SegmentedProps<T extends string = string>
  extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  options: readonly SegmentedOption<T>[]
  value: T
  onChange: (value: T) => void
  ariaLabel?: string
}

/**
 * 05 分段胶囊切换器（外槽 28px/R14 --dsh-surface-sunken - 边距 2px = 内滑块 24px/R12 正圆同心）：
 * - 选中与未选中统一 400 字重，切换零宽度跳动；
 * - 独立滑动指示胶囊由 useSlidingIndicator 驱动，未挂载前自动走 [aria-selected="true"] 兜底；
 * - 悬停仅提亮文字，内置 ← / → / Home / End 漫游焦点。
 */
export function Segmented<T extends string = string>({
  options,
  value,
  onChange,
  ariaLabel,
  className,
  onKeyDown,
  ...rest
}: SegmentedProps<T>) {
  const containerRef = useRef<HTMLDivElement | null>(null)
  useSlidingIndicator(containerRef, value, {
    itemSelector: 'button[role="tab"], .dsh-seg-item, button',
    indicatorClass: 'dsh-seg-ind',
  })

  const firstEnabledIdx = options.findIndex((opt) => !opt.disabled)
  const hasSelected = options.some((opt) => !opt.disabled && opt.value === value)

  return (
    <div
      ref={containerRef}
      role="tablist"
      aria-label={ariaLabel ?? rest['aria-label']}
      className={`dsh-seg${className ? ` ${className}` : ''}`}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (!event.defaultPrevented) {
          handleRovingKeyDown(event, 'button[role="tab"], .dsh-seg-item, button')
        }
      }}
      {...rest}
    >
      {options.map((opt, idx) => {
        const active = opt.value === value
        const stop = !opt.disabled && (active || (!hasSelected && idx === firstEnabledIdx))
        return (
          <button
            key={opt.value}
            type="button"
            role="tab"
            disabled={opt.disabled}
            aria-selected={active}
            tabIndex={stop ? 0 : -1}
            className="dsh-seg-item"
            onClick={() => {
              if (!opt.disabled) onChange(opt.value)
            }}
          >
            {opt.label}
          </button>
        )
      })}
    </div>
  )
}

export interface UnderlineTabOption<T extends string = string> {
  value: T
  label: ReactNode
  icon?: ReactNode
  badge?: ReactNode
  disabled?: boolean
}

export interface UnderlineTabsProps<T extends string = string>
  extends Omit<HTMLAttributes<HTMLDivElement>, 'onChange'> {
  options: readonly UnderlineTabOption<T>[]
  value: T
  onChange: (value: T) => void
  ariaLabel?: string
}

/**
 * 05 面板主导航下划线标签栏（36px 高度 + 2px --dsh-brand-fill 独立滑动底线）：
 */
export function UnderlineTabs<T extends string = string>({
  options,
  value,
  onChange,
  ariaLabel,
  className,
  onKeyDown,
  ...rest
}: UnderlineTabsProps<T>) {
  const containerRef = useRef<HTMLDivElement | null>(null)
  useSlidingIndicator(containerRef, value, {
    itemSelector: '.dsh-utab, button[role="tab"]',
    indicatorClass: 'dsh-utabs-ind',
  })

  const firstEnabledIdx = options.findIndex((opt) => !opt.disabled)
  const hasSelected = options.some((opt) => !opt.disabled && opt.value === value)

  return (
    <div
      ref={containerRef}
      role="tablist"
      aria-label={ariaLabel ?? rest['aria-label']}
      className={`dsh-utabs${className ? ` ${className}` : ''}`}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (!event.defaultPrevented) {
          handleRovingKeyDown(event, '.dsh-utab, button[role="tab"]')
        }
      }}
      {...rest}
    >
      {options.map((opt, idx) => {
        const active = opt.value === value
        const stop = !opt.disabled && (active || (!hasSelected && idx === firstEnabledIdx))
        return (
          <button
            key={opt.value}
            type="button"
            role="tab"
            disabled={opt.disabled}
            aria-selected={active}
            tabIndex={stop ? 0 : -1}
            className="dsh-utab"
            onClick={() => {
              if (!opt.disabled) onChange(opt.value)
            }}
          >
            {opt.icon !== undefined && opt.icon}
            <span>{opt.label}</span>
            {opt.badge !== undefined && opt.badge}
          </button>
        )
      })}
    </div>
  )
}

