import React, { type HTMLAttributes, type ReactNode } from 'react'
import { CheckIcon, ErrorIcon, InfoIcon, SpinnerIcon, SuccessIcon, WarnIcon } from './icons'

/* ---------- 1. StateDot（五态语义圆点 + 步骤完成勾标 + 减动效慢速旋转） ---------- */

export type StateDotState = 'idle' | 'ok' | 'busy' | 'warn' | 'error' | 'done'

export interface StateDotProps extends HTMLAttributes<HTMLSpanElement> {
  state?: StateDotState
  /** 实时活动 / 在线外环高亮（静态环光，避免无限 opacity/scale 合成层重绘）。 */
  pulse?: boolean
  /** 附带右侧行内文字（自动包裹于 .dsh-sdot-item）。 */
  label?: ReactNode
}

export function StateDot({ state = 'idle', pulse = false, label, className, ...rest }: StateDotProps) {
  let dot: ReactNode
  if (state === 'busy') {
    dot = <span className={`dsh-sdot-spin${label === undefined && className ? ` ${className}` : ''}`} aria-hidden="true" />
  } else if (state === 'done') {
    dot = (
      <span className={`dsh-sdot-step${label === undefined && className ? ` ${className}` : ''}`} aria-hidden="true">
        <CheckIcon />
      </span>
    )
  } else {
    const stateCls = state === 'ok'
      ? ' is-ok'
      : state === 'warn'
        ? ' is-warn'
        : state === 'error'
          ? ' is-err'
          : ''
    const pulseCls = pulse ? ' is-pulse' : ''
    dot = (
      <span
        className={`dsh-sdot${stateCls}${pulseCls}${label === undefined && className ? ` ${className}` : ''}`}
        aria-hidden="true"
      />
    )
  }

  if (label !== undefined) {
    return (
      <span {...rest} className={`dsh-sdot-item${className ? ` ${className}` : ''}`}>
        {dot}
        <span>{label}</span>
      </span>
    )
  }
  return (
    <span {...rest} className="dsh-sdot-wrap">
      {dot}
    </span>
  )
}

/* ---------- 2. Badge（20px 正圆弧胶囊徽章：1 描边 + 6 色实底） ---------- */

export type BadgeVariant = 'outline' | 'solid' | 'info' | 'ok' | 'warn' | 'error' | 'subtle' | 'neutral' | 'danger'

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: BadgeVariant
}

export function Badge({ variant = 'outline', className, children, ...rest }: BadgeProps) {
  const variantCls = variant === 'outline'
    ? ''
    : variant === 'subtle' || variant === 'neutral'
      ? ' dsh-badge-subtle dsh-badge-neutral'
      : variant === 'error' || variant === 'danger'
        ? ' dsh-badge-error dsh-badge-danger'
        : ` dsh-badge-${variant}`
  return (
    <span {...rest} className={`dsh-badge${variantCls}${className ? ` ${className}` : ''}`}>
      {children}
    </span>
  )
}

/* ---------- 3. Meter（胶囊进度条 / 绿→琥珀→红实时阈值电平条 / 20 格上下文刻度条） ---------- */

export type MeterVariant = 'bar' | 'level' | 'segments'

export interface MeterProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  variant?: MeterVariant
  /** 百分比数值（0 ~ 100）。 */
  value: number
  label?: ReactNode
  /** 右侧实时读数（自动开启 tabular-nums）；不传则在 showValue 时显示整数百分比。 */
  valueText?: ReactNode
  showValue?: boolean
  /** level 模式触发阈值线位置（0 ~ 100），同时作为绿→琥珀变色起点。 */
  threshold?: number
  warnAt?: number
  errorAt?: number
  /** segments 模式总刻度格数，默认 20 格。 */
  segments?: number
  /** 显式覆盖语义色（默认 bar 走蓝色主进度，level 按阈值自动走绿→琥珀→红）。 */
  tone?: 'default' | 'ok' | 'warn' | 'error'
}

export function Meter({
  variant = 'bar',
  value,
  label,
  valueText,
  showValue,
  threshold,
  warnAt,
  errorAt = 85,
  segments = 20,
  tone,
  className,
  ...rest
}: MeterProps) {
  const pct = Math.min(100, Math.max(0, Number.isFinite(value) ? value : 0))
  const displayValue = valueText ?? (showValue ?? (variant === 'segments' || label !== undefined) ? `${Math.round(pct)}%` : null)
  const a11yLabel = rest['aria-label'] ?? (typeof label === 'string' ? label : '进度')

  if (variant === 'segments') {
    const totalWidth = Math.max(1, segments) * 3 - 1
    const fillPx = Math.round((pct / 100) * totalWidth * 10) / 10
    const segTone = tone ?? (pct >= errorAt ? 'error' : pct >= (warnAt ?? 75) ? 'warn' : 'default')
    const toneCls = segTone === 'error' ? ' is-err' : segTone === 'warn' ? ' is-warn' : segTone === 'ok' ? ' is-ok' : ''
    return (
      <div
        {...rest}
        role="meter"
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={Math.round(pct)}
        aria-label={a11yLabel}
        className={`dsh-meter-seg-wrap${className ? ` ${className}` : ''}`}
      >
        {label !== undefined && <span className="dsh-meter-seg-label">{label}</span>}
        <span className={`comp-ctx-meter dsh-meter-segments${toneCls}`} style={{ width: `${totalWidth}px` }} aria-hidden="true">
          <span style={{ width: `${fillPx}px` }} />
        </span>
        {displayValue !== null && <span className="dsh-meter-seg-val dsh-num">{displayValue}</span>}
      </div>
    )
  }

  const effectiveWarn = warnAt ?? threshold ?? 65
  const resolvedTone = tone ?? (
    variant === 'level'
      ? (pct >= errorAt ? 'error' : pct >= effectiveWarn ? 'warn' : 'ok')
      : 'default'
  )
  const fillCls = resolvedTone === 'ok'
    ? ' is-ok'
    : resolvedTone === 'warn'
      ? ' is-warn'
      : resolvedTone === 'error'
        ? ' is-err'
        : ''
  const clampedThreshold = threshold !== undefined
    ? Math.min(100, Math.max(0, threshold))
    : undefined

  return (
    <div
      {...rest}
      role={variant === 'level' ? 'meter' : 'progressbar'}
      aria-valuemin={0}
      aria-valuemax={100}
      aria-valuenow={Math.round(pct)}
      aria-label={a11yLabel}
      className={`dsh-meter-row${className ? ` ${className}` : ''}`}
    >
      {label !== undefined && <span className="dsh-meter-label">{label}</span>}
      <div className="dsh-meter-track">
        <div className={`dsh-meter-fill${fillCls}`} style={{ width: `${pct}%` }} />
        {clampedThreshold !== undefined && (
          <span
            className="dsh-meter-tick"
            style={{ left: `${clampedThreshold}%` }}
            title={`触发阈值 ${Math.round(clampedThreshold)}%`}
            aria-hidden="true"
          />
        )}
      </div>
      {displayValue !== null && <span className="dsh-meter-num dsh-num">{displayValue}</span>}
    </div>
  )
}

/* ---------- 4. Banner（12px 页内常驻状态横幅 · 严守 1-Border Rule） ---------- */

export type BannerTone = 'info' | 'ok' | 'warn' | 'error'

export interface BannerProps extends HTMLAttributes<HTMLDivElement> {
  tone?: BannerTone
  icon?: ReactNode
  /** 右侧无框动作槽位（推荐搭配 Button ghost / danger-ghost sm）。 */
  action?: ReactNode
}

export function Banner({ tone = 'info', icon, action, className, children, ...rest }: BannerProps) {
  const toneCls = tone === 'error' ? 'is-err is-error' : `is-${tone}`
  const defaultIcon = tone === 'ok'
    ? <SuccessIcon />
    : tone === 'warn'
      ? <WarnIcon />
      : tone === 'error'
        ? <ErrorIcon />
        : <InfoIcon />
  return (
    <div
      role={tone === 'error' || tone === 'warn' ? 'alert' : 'status'}
      {...rest}
      className={`dsh-banner ${toneCls}${className ? ` ${className}` : ''}`}
    >
      <span className="dsh-banner-ico" aria-hidden="true">{icon ?? defaultIcon}</span>
      <span className="dsh-banner-text">{children}</span>
      {action !== undefined && <span className="dsh-banner-act">{action}</span>}
    </div>
  )
}

/* ---------- 5. EmptyState & LoadingState（12px --dsh-surface-sunken 内凹槽） ---------- */

export interface EmptyStateProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  icon?: ReactNode
  title: ReactNode
  description?: ReactNode
  action?: ReactNode
}

export function EmptyState({ icon, title, description, action, className, children, ...rest }: EmptyStateProps) {
  return (
    <div {...rest} className={`dsh-empty${className ? ` ${className}` : ''}`}>
      {icon !== undefined && <div className="dsh-empty-ico" aria-hidden="true">{icon}</div>}
      <p className="dsh-empty-title">{title}</p>
      {description !== undefined && <p className="dsh-empty-sub">{description}</p>}
      {children}
      {action !== undefined && <div className="dsh-empty-act">{action}</div>}
    </div>
  )
}

export interface LoadingStateProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  title?: ReactNode
  description?: ReactNode
}

export function LoadingState({ title = '正在加载…', description, className, children, ...rest }: LoadingStateProps) {
  return (
    <div
      role="status"
      aria-live="polite"
      {...rest}
      className={`dsh-empty dsh-loading${className ? ` ${className}` : ''}`}
    >
      <span className="dsh-loading-spin dsh-sdot-spin" aria-hidden="true">
        <SpinnerIcon />
      </span>
      <p className="dsh-empty-title">{title}</p>
      {description !== undefined && <p className="dsh-empty-sub">{description}</p>}
      {children}
    </div>
  )
}

