import React, { type SVGProps } from 'react'

/**
 * 统一 SVG 图标基础样式（02.6 & 08.3）：
 * - 16x16 视框、1.5px 线条、圆头圆角、currentColor 着色、默认 1em 随字号缩放；
 * - .dsh-icon-inline（vertical-align: -0.125em）对齐正文光学中心；
 * - .dsh-spin 加载旋转在 prefers-reduced-motion 下保留 1.8s 慢速旋转防假死。
 */
export const iconBaseCss = `
@keyframes dsh-spin {
  to { transform: rotate(360deg); }
}
.dsh-icon,
.dsh-i {
  display: inline-block;
  flex: none;
  width: 1em;
  height: 1em;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
  overflow: visible;
}
.dsh-icon-inline,
.dsh-i {
  vertical-align: -0.125em;
}
.dsh-spin {
  transform-origin: 50% 50%;
  animation: dsh-spin var(--dsh-dur-spin, 800ms) linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .dsh-spin {
    animation-duration: 1.8s !important;
    animation-iteration-count: infinite !important;
  }
}
html[data-dsh-reduce-motion] .dsh-spin {
  animation-duration: 1.8s !important;
  animation-iteration-count: infinite !important;
}
`

export interface DshIconProps extends SVGProps<SVGSVGElement> {
  size?: number | string
  inline?: boolean
}

export interface StarIconProps extends DshIconProps {
  filled?: boolean
}

export interface FolderIconProps extends DshIconProps {
  open?: boolean
}

function buildSvgProps(
  { size, inline = true, className, width, height, ...rest }: DshIconProps,
  extraClass?: string,
): SVGProps<SVGSVGElement> {
  const classes = ['dsh-icon']
  if (inline) classes.push('dsh-icon-inline')
  if (extraClass) classes.push(extraClass)
  if (className) classes.push(className)

  const ariaHidden =
    rest['aria-label'] !== undefined || rest['aria-labelledby'] !== undefined
      ? rest['aria-hidden']
      : (rest['aria-hidden'] ?? true)

  return {
    viewBox: '0 0 16 16',
    width: width ?? size ?? '1em',
    height: height ?? size ?? '1em',
    fill: 'none',
    stroke: 'currentColor',
    strokeWidth: 1.5,
    strokeLinecap: 'round',
    strokeLinejoin: 'round',
    focusable: 'false',
    ...rest,
    'aria-hidden': ariaHidden,
    className: classes.join(' '),
  }
}

export function CheckIcon(props: DshIconProps) {
  return (
    <svg {...buildSvgProps(props)}>
      <path d="M3 8.5 6.5 12 13 4.5" />
    </svg>
  )
}

