import React, {
  forwardRef,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type HTMLAttributes,
  type KeyboardEvent as ReactKeyboardEvent,
  type ReactNode,
  type Ref,
  type RefObject,
} from 'react'
import { createPortal } from 'react-dom'
import { MenuSurface } from './MenuSurface'
import { InfoTip } from './InfoTip'
import { ScrollArea } from './ScrollArea'
import { useAnchoredPosition } from './anchored-position'
import { isImeComposing } from './host-bridge'
import { ChevronDownIcon, CloseIcon, SearchIcon, StarIcon } from './icons'
import { handleRovingKeyDown, useSlidingIndicator } from './motion'

export interface PopoverCategory {
  id: string
  label: ReactNode
  disabled?: boolean
}

export interface PopoverProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  /** 是否打开；内联展示时默认 true，锚定弹层时传受控布尔值。 */
  open?: boolean
  onClose?: () => void
  /** 可选触发器引用：传入后通过 useAnchoredPosition 自动锚定定位与视口翻转。 */
  anchorRef?: RefObject<HTMLElement | null>
  side?: 'bottom' | 'top'
  align?: 'start' | 'end'
  gap?: number
  /** 是否通过 createPortal 挂到 document.body（传入 anchorRef 时默认 true，内联展示默认 false）。 */
  portal?: boolean
  material?: 'translucent' | 'solid'
  origin?: CSSProperties['transformOrigin']

  /** 顶栏无框搜索框（严守 1-Border Rule：浮层内不重复画胶囊边框，底部分割线两端缩进 8px）。 */
  searchable?: boolean
  searchValue?: string
  defaultSearchValue?: string
  onSearchChange?: (value: string) => void
  onSearchEnter?: (value: string) => void
  searchPlaceholder?: string
  searchAriaLabel?: string
  clearSearchLabel?: string
  autoFocusSearch?: boolean

  /** 顶栏滑动胶囊分类筛选条（复用 useSlidingIndicator + handleRovingKeyDown）。 */
  categories?: readonly PopoverCategory[]
  activeCategory?: string
  defaultCategory?: string
  onCategoryChange?: (categoryId: string) => void
  categoryAriaLabel?: string
  /** 分类条右侧附加动作槽（例如固定图钉按钮）。 */
  headerExtra?: ReactNode

  /** ScrollArea 列表区最大高度（默认 280px；传 undefined 不限制）。 */
  maxBodyHeight?: number | string
  /** 底部快捷键提示或辅助底栏。 */
  footer?: ReactNode
  style?: CSSProperties
  children?: ReactNode
  [data: `data-${string}`]: string | undefined
}

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>): (node: T | null) => void {
  return (node) => {
    for (const r of refs) {
      if (!r) continue
      if (typeof r === 'function') r(node)
      else (r as { current: T | null }).current = node
    }
  }
}

const HIDDEN_POS: CSSProperties = { left: 0, top: 0, visibility: 'hidden' }

/**
 * 复合弹出面板 Popover（README 06.2）：
 * - 基于 MenuSurface 构建：外框 16px (--dsw-radius-lg) − 内距 6px = 内部行 10px 严格同心；
 * - 可选无框搜索顶栏（SearchIcon + CloseIcon + isImeComposing 选词守卫 + 8px 缩进细分割线）；
 * - 可选滑动胶囊分类条（useSlidingIndicator + Roving Tabindex 方向键漫游）；
 * - 主体列表包裹于 ScrollArea（7 段幂律边缘渐隐 + >2 屏悬浮细滑块）；
 * - 可选底部快捷键提示底栏（.dsh-pop-footer）。
 */
export const Popover = forwardRef<HTMLDivElement, PopoverProps>(function Popover(
  {
    open = true,
    onClose,
    anchorRef,
    side = 'bottom',
    align = 'start',
    gap = 6,
    portal,
    material = 'translucent',
    origin,
    searchable,
    searchValue,
    defaultSearchValue = '',
    onSearchChange,
    onSearchEnter,
    searchPlaceholder = '搜索…',
    searchAriaLabel = '搜索列表',
    clearSearchLabel = '清空搜索',
    autoFocusSearch = false,
    categories,
    activeCategory,
    defaultCategory,
    onCategoryChange,
    categoryAriaLabel = '分类筛选',
    headerExtra,
    maxBodyHeight = 280,
    footer,
    className,
    style,
    children,
    ...rest
  },
  forwardedRef,
) {
  const panelRef = useRef<HTMLDivElement>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)
  const tabsRef = useRef<HTMLDivElement>(null)

  const [uncontrolledSearch, setUncontrolledSearch] = useState(defaultSearchValue)
  const resolvedSearch = searchValue !== undefined ? searchValue : uncontrolledSearch
  const showSearch =
    Boolean(searchable)
    || searchValue !== undefined
    || onSearchChange !== undefined

  const [uncontrolledCat, setUncontrolledCat] = useState(
    () => defaultCategory ?? categories?.[0]?.id ?? '',
  )
  const resolvedCat = activeCategory !== undefined ? activeCategory : uncontrolledCat

  useSlidingIndicator(tabsRef, resolvedCat, {
    itemSelector: '.dsh-pop-tab',
    indicatorClass: 'dsh-pop-tabs-ind',
  })

  const isAnchored = anchorRef !== undefined
  const shouldPortal = portal ?? isAnchored
  const anchoredPos = useAnchoredPosition({
    open: open && isAnchored,
    anchorRef: anchorRef ?? { current: null },
    panelRef,
    side,
    align,
    gap,
    margin: 12,
  })

  useEffect(() => {
    if (!open || !autoFocusSearch || !showSearch) return
    searchInputRef.current?.focus?.()
  }, [open, autoFocusSearch, showSearch])

  useEffect(() => {
    if (!open || !onClose || typeof document === 'undefined') return
    const onPointerDown = (event: PointerEvent) => {
      const target = event.target
      if (!(target instanceof Node)) return
      if (panelRef.current?.contains(target) === true) return
      if (anchorRef?.current?.contains(target) === true) return
      onClose()
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return
      if (isImeComposing(event)) return
      onClose()
    }
    document.addEventListener('pointerdown', onPointerDown, true)
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('pointerdown', onPointerDown, true)
      document.removeEventListener('keydown', onKeyDown)
    }
  }, [open, onClose, anchorRef])

  if (!open) return null

  const updateSearch = (next: string) => {
    if (searchValue === undefined) setUncontrolledSearch(next)
    onSearchChange?.(next)
  }

  const handleSearchKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
    if (isImeComposing(event)) return
    if (event.key === 'Enter') {
      onSearchEnter?.(resolvedSearch)
    } else if (event.key === 'Escape') {
      if (resolvedSearch.length > 0) {
        event.stopPropagation()
        updateSearch('')
      } else {
        onClose?.()
      }
    }
  }

  const selectCategory = (id: string) => {
    if (activeCategory === undefined) setUncontrolledCat(id)
    onCategoryChange?.(id)
  }

  const hasTopBar = (categories !== undefined && categories.length > 0) || headerExtra !== undefined
  const mergedStyle: CSSProperties = isAnchored
    ? { ...(anchoredPos ?? HIDDEN_POS), ...style }
    : { ...style }

  const surface = (
    <MenuSurface
      {...rest}
      ref={mergeRefs(panelRef, forwardedRef)}
      material={material}
      origin={origin}
      data-side={isAnchored ? side : rest['data-side']}
      data-align={isAnchored ? align : rest['data-align']}
      className={`dsh-pop${isAnchored ? ' dsh-pop-anchored' : ''}${className ? ` ${className}` : ''}`}
      style={mergedStyle}
    >
      {showSearch && (
        <div className="dsh-pop-search">
          <span className="dsh-pop-search-ico" aria-hidden="true">
            <SearchIcon />
          </span>
          <input
            ref={searchInputRef}
            type="text"
            className="dsh-pop-search-input"
            value={resolvedSearch}
            placeholder={searchPlaceholder}
            aria-label={searchAriaLabel}
            onChange={(e) => updateSearch(e.target.value)}
            onKeyDown={handleSearchKeyDown}
          />
          {resolvedSearch.length > 0 && (
            <button
              type="button"
              className="dsh-pop-search-clear dsh-search-clear"
              aria-label={clearSearchLabel}
              onClick={() => {
                updateSearch('')
                searchInputRef.current?.focus?.()
              }}
            >
              <CloseIcon />
            </button>
          )}
        </div>
      )}

      {hasTopBar && (
        <div className="dsh-pop-top">
          {categories !== undefined && categories.length > 0 ? (
            <div
              ref={tabsRef}
              className="dsh-pop-tabs"
              role="tablist"
              aria-label={categoryAriaLabel}
              onKeyDown={(e) => handleRovingKeyDown(e, '.dsh-pop-tab')}
            >
              {categories.map((cat) => {
                const selected = cat.id === resolvedCat
                return (
                  <button
                    key={cat.id}
                    type="button"
                    role="tab"
                    tabIndex={selected ? 0 : -1}
                    aria-selected={selected}
                    disabled={cat.disabled}
                    className="dsh-pop-tab"
                    onClick={() => selectCategory(cat.id)}
                  >
                    {cat.label}
                  </button>
                )
              })}
            </div>
          ) : (
            <span />
          )}
          {headerExtra !== undefined && (
            <div className="dsh-pop-extra">{headerExtra}</div>
          )}
        </div>
      )}

      <ScrollArea
        maxHeight={maxBodyHeight}
        className="dsh-pop-scroll"
        viewportClassName="dsh-pop-body"
      >
        {children}
      </ScrollArea>

      {footer !== undefined && (
        <div className="dsh-pop-footer">{footer}</div>
      )}
    </MenuSurface>
  )

  if (shouldPortal && typeof document !== 'undefined' && Boolean(document.body)) {
    return createPortal(surface, document.body)
  }
  return surface
})

/* ---------- PopoverRow & PopoverGroup 辅助子原语 ---------- */

export interface PopoverRowProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title' | 'onSelect'> {
  icon?: ReactNode
  title: ReactNode
  alias?: ReactNode
  description?: ReactNode
  info?: ReactNode
  infoLabel?: string
  starred?: boolean
  onToggleStar?: () => void
  starLabel?: string
  selected?: boolean
  disabled?: boolean
  onSelect?: () => void
  trailing?: ReactNode
}

export function PopoverRow({
  icon,
  title,
  alias,
  description,
  info,
  infoLabel,
  starred,
  onToggleStar,
  starLabel = '收藏',
  selected = false,
  disabled = false,
  onSelect,
  trailing,
  className,
  onClick,
  onKeyDown,
  ...rest
}: PopoverRowProps) {
  const interactive = onSelect !== undefined || onClick !== undefined
  return (
    <div
      role={interactive ? 'option' : undefined}
      aria-selected={interactive ? selected : undefined}
      aria-disabled={disabled || undefined}
      tabIndex={interactive && !disabled ? 0 : undefined}
      {...rest}
      className={`dsh-pop-row${selected ? ' is-selected' : ''}${disabled ? ' is-disabled' : ''}${className ? ` ${className}` : ''}`}
      onClick={(event) => {
        if (disabled) return
        onClick?.(event)
        onSelect?.()
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        if (event.defaultPrevented || disabled || isImeComposing(event)) return
        if (interactive && (event.key === 'Enter' || event.key === ' ')) {
          event.preventDefault()
          onSelect?.()
        }
      }}
    >
      {icon !== undefined && <span className="hs-fb-icon">{icon}</span>}
      <span className="dsh-pop-title">{title}</span>
      {alias !== undefined && <span className="dsh-pop-alias">{alias}</span>}
      {description !== undefined && <span className="dsh-pop-desc">{description}</span>}
      {trailing}
      {info !== undefined && info !== null && info !== '' && (
        <InfoTip content={info} label={infoLabel} preventFocusSteal />
      )}
      {(starred !== undefined || onToggleStar !== undefined) && (
        <button
          type="button"
          className="dsh-pop-star"
          aria-pressed={Boolean(starred)}
          aria-label={starLabel}
          onClick={(event) => {
            event.stopPropagation()
            onToggleStar?.()
          }}
        >
          <StarIcon filled={Boolean(starred)} />
        </button>
      )}
    </div>
  )
}

export interface PopoverGroupProps extends Omit<HTMLAttributes<HTMLDivElement>, 'title'> {
  title: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  children?: ReactNode
}

export function PopoverGroup({
  title,
  open,
  defaultOpen = true,
  onOpenChange,
  className,
  children,
  ...rest
}: PopoverGroupProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isOpen = open !== undefined ? open : uncontrolledOpen

  const toggle = () => {
    const next = !isOpen
    if (open === undefined) setUncontrolledOpen(next)
    onOpenChange?.(next)
  }

  return (
    <div {...rest} className={`dsh-pop-group${className ? ` ${className}` : ''}`}>
      <button
        type="button"
        className="dsh-pop-ghead"
        aria-expanded={isOpen}
        onClick={toggle}
      >
        <span className="dsh-pop-gchev" aria-hidden="true">
          <ChevronDownIcon />
        </span>
        <span>{title}</span>
      </button>
      <div className="dsh-pop-gbody" hidden={!isOpen}>
        {children}
      </div>
    </div>
  )
}

