import React, {
  forwardRef,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type CSSProperties,
  type ReactNode,
  type Ref,
} from 'react'
import { createPortal } from 'react-dom'
import { MenuSurface } from './MenuSurface'
import { isImeComposing } from './host-bridge'
import { InfoIcon } from './icons'

export interface InfoTipAnchorRect {
  top: number
  bottom: number
  right: number
}

export interface InfoTipPlacement {
  left: number
  width: number
  top?: number
  bottom?: number
}

export interface PlaceInfoTipOptions {
  maxWidth?: number
  gap?: number
  margin?: number
  roomAbove?: number
}

/**
 * 计算说明按钮浮层位置：
 * - 右缘尽量对齐按钮右缘并夹紧视口左右边距；
 * - 按钮上方空间充足（>= roomAbove）时贴紧按钮上缘向上生长（返回 bottom），否则翻转到下方（返回 top）。
 */
export function placeInfoTip(
  anchor: InfoTipAnchorRect,
  viewport: { width: number; height: number },
  options?: PlaceInfoTipOptions,
): InfoTipPlacement {
  const maxWidth = options?.maxWidth ?? 300
  const gap = options?.gap ?? 6
  const margin = options?.margin ?? 12
  const roomAbove = options?.roomAbove ?? 140

  const width = Math.max(0, Math.min(maxWidth, viewport.width - margin * 2))
  const left = Math.max(
    margin,
    Math.min(Math.round(anchor.right - width), viewport.width - width - margin),
  )

  if (anchor.top >= roomAbove) {
    return {
      left,
      width,
      bottom: Math.round(viewport.height - anchor.top + gap),
    }
  }

  return {
    left,
    width,
    top: Math.round(anchor.bottom + gap),
  }
}

export interface InfoTipProps
  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'content' | 'type' | 'children'> {
  /** 详情说明正文（支持多行文本或自定义节点；为空时不渲染按钮）。 */
  content: ReactNode
  /** 按钮无障碍标签（默认「查看说明」）。 */
  label?: string
  /** 尺寸：sm=24px（适配列表行内操作），md=28px（--dsh-control-sm）。 */
  size?: 'sm' | 'md'
  /** 鼠标悬停展开延迟（毫秒，默认 120ms）。 */
  delayMs?: number
  /** 浮层最大宽度（默认 300px）。 */
  maxWidth?: number
  /** 点击时是否阻止抢走输入框焦点（如斜杠面板等场景，默认 false）。 */
  preventFocusSteal?: boolean
  /** 是否通过 Portal 挂载到 document.body（默认 true）。 */
  portal?: boolean
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  popClassName?: string
}

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>): (node: T | null) => void {
  return (node) => {
    for (const ref of refs) {
      if (!ref) continue
      if (typeof ref === 'function') ref(node)
      else (ref as { current: T | null }).current = node
    }
  }
}

/**
 * 06 说明按钮与多行详情浮层（InfoTip）：
 * - 正圆 ⓘ 图标钮（24px sm / 28px md）+ 12px 紧凑毛玻璃多行气泡（MenuSurface compact）；
 * - 桌面端悬停 120ms 轻扫展开，触屏与键盘点击（Enter / Space）切换并阻断冒泡防误触整行。
 */
export const InfoTip = forwardRef<HTMLButtonElement, InfoTipProps>(function InfoTip(
  {
    content,
    label = '查看说明',
    size = 'sm',
    delayMs = 120,
    maxWidth = 300,
    preventFocusSteal = false,
    portal = true,
    open: controlledOpen,
    defaultOpen = false,
    onOpenChange,
    className,
    popClassName,
    onPointerEnter,
    onPointerLeave,
    onMouseDown,
    onClick,
    onKeyDown,
    ...rest
  },
  forwardedRef,
) {
  const tipId = useId()
  const btnRef = useRef<HTMLButtonElement | null>(null)
  const popRef = useRef<HTMLDivElement | null>(null)
  const timerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const pinnedRef = useRef(false)

  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen)
  const isControlled = controlledOpen !== undefined
  const isOpen = isControlled ? controlledOpen : uncontrolledOpen
  const [place, setPlace] = useState<InfoTipPlacement | null>(null)

  const computePlace = useCallback((): InfoTipPlacement | null => {
    const btn = btnRef.current
    if (!btn || typeof window === 'undefined') return null
    const rect = btn.getBoundingClientRect()
    const vv = window.visualViewport
    return placeInfoTip(
      rect,
      { width: vv?.width ?? window.innerWidth, height: window.innerHeight },
      { maxWidth },
    )
  }, [maxWidth])

  const closeTip = useCallback(() => {
    clearTimeout(timerRef.current)
    pinnedRef.current = false
    if (!isControlled) setUncontrolledOpen(false)
    onOpenChange?.(false)
  }, [isControlled, onOpenChange])

  const openTip = useCallback(
    (pinned: boolean) => {
      clearTimeout(timerRef.current)
      pinnedRef.current = pinned
      const nextPlace = computePlace()
      if (nextPlace) setPlace(nextPlace)
      if (!isControlled) setUncontrolledOpen(true)
      onOpenChange?.(true)
    },
    [computePlace, isControlled, onOpenChange],
  )

  useEffect(() => () => clearTimeout(timerRef.current), [])

  useEffect(() => {
    if (!isOpen) {
      pinnedRef.current = false
      clearTimeout(timerRef.current)
      return undefined
    }
    const nextPlace = computePlace()
    if (nextPlace) setPlace(nextPlace)

    if (typeof document === 'undefined' || typeof window === 'undefined') return undefined

    const onDocKeyDown = (event: KeyboardEvent) => {
      if (isImeComposing(event)) return
      if (event.key === 'Escape') {
        event.stopPropagation()
        closeTip()
      }
    }
    const onDocPointerDown = (event: PointerEvent) => {
      const target = event.target
      if (!(target instanceof Node)) return
      if (btnRef.current?.contains(target)) return
      if (popRef.current?.contains(target)) return
      closeTip()
    }
    const onScroll = (event: Event) => {
      const target = event.target
      if (target instanceof Node && popRef.current?.contains(target)) return
      closeTip()
    }

    document.addEventListener('keydown', onDocKeyDown)
    document.addEventListener('pointerdown', onDocPointerDown, true)
    window.addEventListener('blur', closeTip)
    window.addEventListener('scroll', onScroll, true)

    return () => {
      document.removeEventListener('keydown', onDocKeyDown)
      document.removeEventListener('pointerdown', onDocPointerDown, true)
      window.removeEventListener('blur', closeTip)
      window.removeEventListener('scroll', onScroll, true)
    }
  }, [isOpen, computePlace, closeTip])

  if (content === undefined || content === null || content === '') {
    return null
  }

  const resolvedPlace: InfoTipPlacement = place ?? { left: 0, width: maxWidth, top: 0 }
  const popStyle: CSSProperties = {
    left: resolvedPlace.left,
    width: resolvedPlace.width,
    top: resolvedPlace.top,
    bottom: resolvedPlace.bottom,
    ...(typeof window !== 'undefined' && place === null ? { visibility: 'hidden' } : {}),
  }
  const popSide = resolvedPlace.top !== undefined ? 'bottom' : 'top'
  const popOrigin = popSide === 'bottom' ? 'top right' : 'bottom right'

  const popNode = isOpen ? (
    <MenuSurface
      ref={popRef}
      compact
      material="translucent"
      id={tipId}
      role="tooltip"
      origin={popOrigin}
      data-side={popSide}
      data-align="end"
      data-pop-anim="true"
      className={`dsh-infotip-pop${popClassName ? ` ${popClassName}` : ''}`}
      style={popStyle}
      onPointerLeave={(event) => {
        if (pinnedRef.current) return
        const related = event.relatedTarget
        if (related instanceof Node && btnRef.current?.contains(related)) return
        closeTip()
      }}
    >
      <div className="dsh-infotip-body">{content}</div>
    </MenuSurface>
  ) : null

  const canPortal = portal && typeof document !== 'undefined' && Boolean(document.body)

  return (
    <>
      <button
        {...rest}
        ref={mergeRefs(btnRef, forwardedRef)}
        type="button"
        aria-label={label}
        aria-expanded={isOpen}
        aria-describedby={isOpen ? tipId : undefined}
        className={`dsh-infotip-btn${size === 'md' ? ' dsh-infotip-btn-md' : ''}${className ? ` ${className}` : ''}`}
        onPointerEnter={(event) => {
          onPointerEnter?.(event)
          if (event.pointerType === 'touch') return
          clearTimeout(timerRef.current)
          if (isOpen) return
          pinnedRef.current = false
          const openHover = () => {
            if (btnRef.current && btnRef.current.isConnected === false) return
            openTip(false)
          }
          if (delayMs <= 0) openHover()
          else timerRef.current = setTimeout(openHover, delayMs)
        }}
        onPointerLeave={(event) => {
          onPointerLeave?.(event)
          clearTimeout(timerRef.current)
          if (!isOpen || pinnedRef.current) return
          const related = event.relatedTarget
          if (related instanceof Node && popRef.current?.contains(related)) return
          closeTip()
        }}
        onMouseDown={(event) => {
          if (preventFocusSteal) {
            event.preventDefault()
            event.stopPropagation()
          }
          onMouseDown?.(event)
        }}
        onClick={(event) => {
          event.stopPropagation()
          onClick?.(event)
          if (event.defaultPrevented) return
          if (isOpen) closeTip()
          else openTip(true)
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event)
          if (event.defaultPrevented || isImeComposing(event)) return
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault()
            event.stopPropagation()
            if (isOpen) closeTip()
            else openTip(true)
          }
        }}
      >
        <InfoIcon size={14} inline={false} />
      </button>
      {popNode !== null
        ? canPortal
          ? createPortal(popNode, document.body)
          : popNode
        : null}
    </>
  )
})

export const infoTipCss = `
.dsh-infotip-btn {
  all: unset;
  box-sizing: border-box;
  position: relative;
  flex: none;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  corner-shape: round;
  display: inline-grid;
  place-items: center;
  color: var(--dsw-alias-label-caption, var(--dsw-alias-label-tertiary));
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transition:
    background var(--dsh-dur-hover, 120ms) ease,
    color var(--dsh-dur-hover, 120ms) ease,
    transform var(--dsh-dur-release, 150ms) var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-infotip-btn-md {
  width: var(--dsh-control-sm, 28px);
  height: var(--dsh-control-sm, 28px);
}
.dsh-infotip-btn::after {
  content: "";
  position: absolute;
  inset: -4px;
  border-radius: 50%;
  corner-shape: round;
}
@media (pointer: coarse) {
  .dsh-infotip-btn::after {
    inset: -6px;
  }
}
.dsh-infotip-btn:active {
  transform: scale(.93);
  transition-duration: var(--dsh-dur-press, 60ms);
  transition-timing-function: var(--dsh-ease-out, cubic-bezier(.22, 1, .36, 1));
}
.dsh-infotip-btn:focus-visible {
  outline: var(--dsw-focus-ring-width, 2px) solid var(--dsh-focus-ring-color);
  outline-offset: -2px;
}
.dsh-infotip-btn[aria-expanded="true"] {
  background: var(--dsw-alias-interactive-bg-hover);
  color: var(--dsw-alias-label-primary);
}
@media (hover: hover) {
  .dsh-infotip-btn:hover {
    background: var(--dsw-alias-interactive-bg-hover);
    color: var(--dsw-alias-label-primary);
  }
}
.hs-msurf.dsh-infotip-pop {
  position: fixed;
  z-index: 1150;
  box-sizing: border-box;
  max-width: min(300px, calc(100vw - 24px));
  overflow: visible;
  padding: 8px 10px;
  color: var(--dsw-alias-label-primary);
  font-size: var(--dsh-text-sm, 12px);
  line-height: 18px;
  pointer-events: auto;
}
.dsh-infotip-body {
  max-height: calc(40vh - 16px);
  overflow-y: auto;
  overscroll-behavior: contain;
  scrollbar-width: none;
  white-space: pre-wrap;
  text-wrap: pretty;
  overflow-wrap: anywhere;
}
.dsh-infotip-body::-webkit-scrollbar {
  display: none;
}
`
